        Buff_Content_100 = {
          ContentJP = "超凶悪な敵ユニットのHPが#1まで下がるときに、無敵状態に入る。#2秒間継続。同時に、一定の数の敵が増援する。敵を撃破すると味方全体に「与ダメージアップ#3」の効果を1スタック付与（最大#4スタック）。一定数の敵を倒すと、超凶悪な敵ユニットの無敵状態を早期に解除できる。"
        },
        Buff_Content_101 = {
          ContentJP = "敵ユニットは選択した元素属性が付与され、<H>有利</>属性ダメージが<H>400%</>増加し、<W>不利</>属性ダメージは<W>50%</>減少する。"
        },
        Buff_Content_11111 = {
          ContentJP = "敵ユニットの被ダメージが#1ダウンする。敵ユニットが異なる味方ユニットからダメージを受けた時に、この効果によりのダメージ軽減が#2ダウンする。"
        },
        Buff_Content_11113 = {
          ContentJP = "味方ユニットが他の味方からの治療によってHPを回復すると、攻撃速度が#1、スキル速度が#2アップ、#3秒継続し、最大#4スタックまで重ねがけできる。最大重ねがけ時、ダメージを受けてものけ反らない。"
        },
        Buff_Content_11121 = {
          ContentJP = "味方ユニットが最大HPの#1分のHPを失うたびに、クリティカル率が#2アップし、#3秒間持続する。最大#4スタックまで重ねがけできる。"
        },
        Buff_Content_11122 = {
          ContentJP = "味方ユニットの武器ダメージが#1ダウンし、クリティカルダメージが#2アップする。"
        },
        Buff_Content_11211 = {
          ContentJP = "味方ユニットのHPが#1%以上のとき、スキル威力が#2アップし、ダメージを受けてものけ反らない。"
        },
        Buff_Content_11212 = {
          ContentJP = "味方ユニットのクリティカルダメージが#1ダウンし、持続ダメージが#2アップする。"
        },
        Buff_Content_11221 = {
          ContentJP = "近接攻撃を行うと、武器ダメージが#1アップ、#2秒継続し、最大#3スタックまで重ねがけできる。最大重ねがけ時、ダメージを受けてものけ反らない。"
        },
        Buff_Content_11222 = {
          ContentJP = "味方ユニットの与ダメージが#1ダウンし、クリティカル率が#2アップする。"
        },
        Buff_Content_12111 = {
          ContentJP = "味方ユニットがバトルスキルまたは必殺技を発動すると、「高揚」が#1上昇する。#2秒間持続。"
        },
        Buff_Content_12112 = {
          ContentJP = "味方ユニットのダメージが#1ダウンし、武器ダメージが#2アップする。"
        },
        Buff_Content_12121 = {
          ContentJP = "味方ユニットがバトルスキルまたは必殺技を発動すると、与えるスキルダメージが#1上昇、#2秒間持続し、最大#3スタックまで重ねがけできる。最大重ねがけ時、ダメージを受けてものけ反らない。"
        },
        Buff_Content_12211 = {
          ContentJP = "味方ユニットがバトルスキルまたは必殺技を発動すると、自身と味方にスキル威力#1上昇を付与する。#2秒間持続し、異なるユニット由来の効果は重ねがけ可能。"
        },
        Buff_Content_12221 = {
          ContentJP = "味方ユニットがダメージ#1回を与える度に、 #3秒の間与ダメージが#2アップする。最大#4スタックまで重ねがけできる。"
        },
        Buff_Content_13111 = {
          ContentJP = "味方ユニットがバトルスキルまたは必殺技を発動すると、#2秒の間に高揚が#1アップする。最大#3スタックまで重ねがけできる。"
        },
        Buff_Content_13112 = {
          ContentJP = "味方ユニットのスキル耐久が#1ダウンし、スキル範囲が#2アップする。"
        },
        Buff_Content_13121 = {
          ContentJP = "滞空中にダメージを与えると。与ダメージが#1アップする。この効果は着地後#2秒後に解除される。"
        },
        Buff_Content_13122 = {
          ContentJP = "味方ユニットの攻撃力が#1ダウンし、スキル威力が#2アップする。"
        },
        Buff_Content_13211 = {
          ContentJP = "味方ユニットが#1SPを消費すると、 #3秒の間与ダメージが#2アップする。最大#4スタックまで重ねがけできる。"
        },
        Buff_Content_13212 = {
          ContentJP = "味方ユニットの最大HPが#1ダウンし、最大SPが#2アップする。"
        },
        Buff_Content_13222 = {
          ContentJP = "味方ユニットの攻撃力が#1ダウンし、多重射撃が#2アップする。"
        },
        Buff_Content_14111 = {
          ContentJP = "味方ユニットがクリティカルダメージを#1回与える度に、#3秒の間に攻撃力が#2アップする。最大#4スタックまで重ねがけできる。"
        },
        Buff_Content_14121 = {
          ContentJP = "味方ユニットがバトルスキルまたは必殺技を発動すると、#2秒の間与ダメージが#1アップする。最大#3スタックまで重ねがけできる。"
        },
        Buff_Content_14122 = {
          ContentJP = "味方ユニットの攻撃力が#1ダウンし、クリティカル率が#2アップする。"
        },
        Buff_Content_14212 = {
          ContentJP = "味方ユニットの攻撃力が#1ダウンし、高揚が#2アップする。"
        },
        Buff_Content_14221 = {
          ContentJP = "味方ユニットがバトルスキルまたは必殺技を発動すると、#2秒の間にスキル威力が#1アップする。最大#3スタックまで重ねがけできる。"
        },
        Buff_Content_15111 = {
