        Content_10040507_01 = {
          ContentJP = "ここはどこだ……？"
        },
        Content_110101_1 = {
          ContentJP = "誰かがあなたを呼んでいるような気がする……"
        },
        Content_110101_2 = {
          ContentJP = "奇妙に声に惑わされるな。先へと進み、この悪夢から立ち去れ。"
        },
        Content_110102_1 = {
          ContentJP = "悪夢から目覚めると、穢獣の鋭利な牙が目の前にあった。"
        },
        Content_110102_2 = {
          ContentJP = "あなたの小隊は強力な穢獣に襲われた。穢獣を倒してから、隊員たちと合流しよう。"
        },
        Content_110103_1 = {
          ContentJP = "いきなり現れた穢獣を倒し、一時的に危機を脱した。臨時救護所に向かい、隊員たちと合流しよう。"
        },
        Content_110103_2 = {
          ContentJP = "あなたの小隊は戦闘で多くの死傷者を出した。衛生兵のダフネは、生き残った負傷者たちと話をしてほしいと頼んできた。\n同時に、ダフネが倉庫で緊急医療物資を調達しようとしていることを知った。安全上の懸念から、あなたは彼女の代わりに物資を調達することを決意した。"
        },
        Content_110103_3 = {
          ContentJP = "廊下の方向から突然、穢獣の大群が襲いかかってきた。負傷者たちはもはや戦意を失っている。隊長であり、最後の戦力であるあなたは、戦線を死守し、仲間たちを守らねばならない。"
        },
        Content_110103_3_2 = {
          ContentJP = "アヴァールが支援に駆けつけ、戦局をひっくり返した。 穢獣のボスを撃破し、この戦闘に終止符を打とう。"
        },
        Content_110103_4 = {
          ContentJP = "アヴァールと共に穢獣を撃退して臨時救護所に戻り、次の行動計画を検討しよう。"
        },
        Content_110104_1 = {
          ContentJP = "アヴァールはダフネと負傷者たちに「白狼」小隊の迎えを待つよう指示した。あなたは彼と一緒に要塞内部に侵入し、任務を続行することにした。"
        },
        Content_110104_2 = {
          ContentJP = "アヴァールは戦況を分析し、フォーセイクン同盟が帝国の作戦を予測していると判断した。戦略的に不利な状況だ。\n慎重に検討した結果、まず機関室へ向かい、イコルキャビンを破壊することで要塞内で稼働している機関を強制的に停止させ、閉じ込められた兵士たちを救出する計画を立てた。"
        },
        Content_110104_3 = {
          ContentJP = "アヴァールは戦況を分析し、フォーセイクン同盟が帝国の作戦を予測していると判断した。戦略的に不利な状況だ。\n慎重に検討した結果、まず機関室へ向かい、イコルキャビンを破壊することで要塞内で稼働している機関を強制的に停止させ、閉じ込められた兵士たちを救出する計画を立てた。"
        },
        Content_110105_1 = {
          ContentJP = "あなたたちは「白狼」小隊の2人の隊員を見つけたが、そのうちの1人、ヴィックが機関室の中に閉じ込められている。\nアヴァールと協力して電源を切り、一刻も早く仲間を救助しよう。"
        },
        Content_110105_2 = {
