        },
        Content_120112_5_1 = {
          ContentJP = "ユニコーン{性别:氏|嬢}の導きでここに来た。周囲を調べてみよう。"
        },
        Content_120112_5_2 = {
          ContentJP = "重要な手掛かりを見つけた。物言わぬ探偵に渡して分析してもらおう。"
        },
        Content_120112_6 = {
          ContentJP = "今日の冒険も無事終了。暗くなる前に家に帰って休もう。"
        },
        Content_120112_6_2 = {
          ContentJP = "ユニコーン{性别:氏|嬢}が何か発見したようだ。ついて行こう。"
        },
        Content_120112_7 = {
          ContentJP = "ユニコーン{性别:氏|嬢}の導きで、別のユニコーン{性别:氏|嬢}に出会った。不思議な一日だった。早く帰って今日の出来事を記録しよう。"
        },
        Content_120113_0 = {
          ContentJP = "フィーナの家へ行き、物語を続ける"
        },
        Content_120113_1 = {
          ContentJP = "新しい一日が始まった。家を出て今日の冒険の旅に出よう。"
        },
        Content_120113_2 = {
          ContentJP = "昨日広場で物言わぬ探偵に会った。今日は誰に出会えるだろう？行ってみよう。"
        },
        Content_120113_3 = {
          ContentJP = "ユニコーン{性别:氏|嬢}と一緒に広場へ行き、先ほどの貴族の少女を探そう。"
        },
        Content_120113_4 = {
          ContentJP = "カサンドラと会う日を約束した。依頼を果たすために急いで魔法の練習をしよう。"
        },
        Content_120113_5 = {
          ContentJP = "魔導書を開き、物語「茨を越える渓谷」を完結させ、蝶々さんを召喚する魔法を学ぶ。"
        },
        Content_120113_6 = {
          ContentJP = "夜も更けた。休もう。"
        },
        Content_120114_0 = {
          ContentJP = "フィーナの家へ行き、物語を続ける"
        },
        Content_120114_1 = {
          ContentJP = "約束の日が来た。ユニコーン{性别:氏|嬢}と合流して、カサンドラに会いに行こう。"
        },
        Content_120114_10_1 = {
          ContentJP = "小さなナイチンゲールはついに勇気を得て、自らの翼を広げた。"
        },
        Content_120114_10_2 = {
          ContentJP = "冒険は見事に幕を閉じた。仲間たちと一緒に帰ろう。"
        },
        Content_120114_10_3 = {
          ContentJP = "冒険は見事に幕を閉じた。仲間たちと一緒に帰ろう。"
        },
        Content_120114_10_4 = {
          ContentJP = "カサンドラが治安署の兵士を連れてきた。危機はようやく去った。彼女と話をしよう。"
        },
        Content_120114_11 = {
          ContentJP = "夜は皆と家でお茶会の約束だ。準備のために帰ろう。"
        },
        Content_120114_12 = {
          ContentJP = "ノックの音がした。扉を開けて誰が来たのか確かめよう。"
        },
        Content_120114_13 = {
          ContentJP = "魔導書を開き、物語「香る草原へ」を完結させ、小さなナイチンゲールを召喚する魔法を学ぶ。"
        },
        Content_120114_2 = {
          ContentJP = "約束の日が来た。ユニコーン{性别:氏|嬢}と合流して、カサンドラに会いに行こう。"
        },
        Content_120114_3 = {
          ContentJP = "ユニコーン{性别:氏|嬢}と一緒に、カサンドラとの約束の場所へ向かう。"
        },
        Content_120114_3_1 = {
          ContentJP = "カサンドラと口裏を合わせ、ここで彼女が友人を連れてくるのを待とう。"
        },
        Content_120114_4 = {
          ContentJP = "まさかカサンドラの友人が彼だったとは……急いで帰って身を隠そう。"
        },
        Content_120114_5 = {
          ContentJP = "子供たちの情報によれば、マークがセヴィオの行方を知っているかもしれない。尋ねてみよう。"
        },
        Content_120114_5_1 = {
          ContentJP = "マークはセヴィオが城外に行ったのを見た。急いで追いかけよう。"
        },
        Content_120114_6 = {
          ContentJP = "マークはセヴィオが城外に行ったのを見た。急いで追いかけよう。"
        },
        Content_120114_7 = {
          ContentJP = "これまでの捜査で得た情報から、セヴィオは山賊に囚われている可能性が高い。拠点はダクリ湖の近くにあるはずだ。ユニコーン{性别:氏|嬢}と共に急ごう。"
        },
        Content_120114_8 = {
          ContentJP = "やはりセヴィオは山賊に囚われていた。救い出さねば。"
        },
        Content_120114_9 = {
          ContentJP = "山賊を倒し、セヴィオを救い出す。"
        },
        Content_120114_9_1 = {
          ContentJP = "戦闘の音が穢獣を引き寄せた。そいつらも倒そう。"
        },
        Content_120201_1 = {
          ContentJP = "燭陰を封印しようとしたそのとき、シリュウが突如として敵対し、あなたを幽閉した。だが、駆けつけたフーシュとカシュウの助けにより、あなたは無事にシリュウの術式から解放された。ひとまず危機は去ったかに思えたが、新たな脅威はすでに迫っていた。塵砂の荒海を出ようとした瞬間、あなたとスノウは呪符に襲われ、その瞬間、あなたの記憶が途切れた。"
        },
        Content_120201_10 = {
          ContentJP = "人で賑わう祀煙閣と違って、匠矩閣の前はまるで人影がない。係員に話を聞いてみよう。"
        },
        Content_120201_11 = {
          ContentJP = "あなたは一人の職人を見つけた。彼は既に儀式用の奉香炉を隣の階段に置いていた。"
        },
        Content_120201_11_2 = {
          ContentJP = "3人の通行人と話したあと、職人が出てきた"
        },
        Content_120201_12 = {
          ContentJP = "執律閣の鐘が突然、鳴り響いた。職人の話によれば、これは百年に一度の珍しい出来事だという。鐘が鳴るのは、複雑な犯罪が起きたときだけだ。\n いったい何が起こったのか。執律閣前の広場へ向かい、掲示されている町触で確認しよう。"
        },
        Content_120201_2 = {
          ContentJP = "塵砂の荒海を出ようとした瞬間、あなたとスノウは呪符に襲われ、その瞬間、あなたの記憶が途切れた。\n どこか見知らぬ場所で何かを巡って激しく対立した――そんな断片的な記憶だけが残っている。あれは現実だったのか、それとも幻覚にすぎないのか。"
        },
        Content_120201_22 = {
          ContentJP = "シリュウに別れを告げ、あなたとスノウは奉香の儀に必要な物資を受け取りに、参商港・祀煙閣・匠矩閣の三か所へ向かうことになった。\n 港の責任者によれば、上質な絹布は隣の倉庫に置いてある。該当する荷箱を探そう。"
        },
        Content_120201_22_1 = {
          ContentJP = "倉庫の荷箱を見つけたあなたたちだったが、ショウヨウセイを名乗るいたずら好きのムユウセイが横から割り込み、あなたたちより一足先に上質な絹布を奪っていった。\n 好きにはさせない。急いで追いかけよう！"
        },
        Content_120201_23 = {
          ContentJP = "屋上で風に飛ばされた香袋を見つけた。いまは持ち主に返しに行こう。"
        },
        Content_120201_24 = {
          ContentJP = "誤解から始まった騒動も収まり、あなたは無事に皓煙香を受け取った。さらに高尚な美談まで残した。\n 向かいの匠矩閣へ行き、任務を続けよう。"
        },
        Content_120201_25 = {
          ContentJP = "奉香の儀が近づき、祀煙閣の前は人で溢れ返っていた。\n 割り込みだと誤解した女性と、ちょっとした揉め事になる。言い合っている最中、突風が吹き、彼女が大切にしていた祭り限定の香袋が飛ばされてしまった。大人の度量を見せて、香袋を探してあげよう。"
        },
        Content_120201_3 = {
          ContentJP = "気づくと、あなたはスノウとシリュウとともにに京の繁華街を歩いていた。スノウの話によれば、燭陰討伐の祝賀会の後、近くの京へ散策に出たという。しかし、その途中であなたの様子がおかしいことに気づいたらしい。スノウをきっかけに、あなたは直前の出来事をかすかに思い出すものの、多くはまだ霧の中だ。\n 青ざめたあなたの顔を見て、シリュウはこの先の薬局で薬草を買い、体調を整えてからツアーを続けようと提案した。"
        },
        Content_120201_4 = {
          ContentJP = "東市は観光客で賑わっている。あなたの強い要望により、スノウは先に席へ向かい、あなたとシリュウは澤生閣で薬を購入することにした。"
        },
        Content_120201_5 = {
          ContentJP = "シリュウの様子に特に異常は見られない。やはり先ほどのはただの妄想だったのだろうか、とあなたは思った。\n 煎じたての薬を受け取ったら、スノウのもとへ戻ろう。"
        },
        Content_120201_6 = {
          ContentJP = "ひと休みしていると、周囲の通行人が執律閣について話しているのが耳に入り、あなたの興味を掻き立てた。\n ちょうどその時、シリュウから奉香の儀に関する依頼を受けており、執律閣の景色を見る機会もありそうだ。\n シリュウとともに西区にある泉通閣へ向かい、信物を手に入れよう。"
        },
        Content_120201_7 = {
          ContentJP = "ひと休みしていると、周囲の通行人が執律閣について話しているのが耳に入り、あなたの興味を掻き立てた。\n ちょうどその時、シリュウから奉香の儀に関する依頼を受けており、執律閣の景色を見る機会もありそうだ。\n シリュウとともに西区にある泉通閣へ向かい、信物を手に入れよう。"
        },
        Content_120201_8 = {
          ContentJP = "シリュウと別れ、あなたとスノウは参商港、祀煙閣、匠矩閣の3カ所を巡り、奉香の儀に必要な物資を調達する予定だ。\n まずは参商港へ行き、港の責任者を探そう。"
        },
        Content_120201_8_1 = {
          ContentJP = "シリュウと別れ、あなたとスノウは参商港、祀煙閣、匠矩閣の3カ所を巡り、奉香の儀に必要な物資を調達する予定だ。\n まずは参商港へ行き、港の責任者を探そう。"
        },
        Content_120201_9 = {
          ContentJP = "紆余曲折の末に、あなたは「ショウヨウセイ」という名のいたずら好きなムユウセイから上質な絹織物を取り戻した。\n 続いて内城の祀煙閣へ向かい、クエストを進めよう。"
        },
        Content_120202_1 = {
          ContentJP = "少し前のこと。ある雨の夜、カシュウはたった一人で狴犴と激戦を繰り広げていた……"
        },
        Content_120202_10 = {
          ContentJP = "危急の瞬間、身を守るため、あなたはやむなく龍神の攻勢を受け止めた。\n 攻防が最も拮抗した刹那、あなたの力が制御不能のまま噴き出し、龍神は傷を負って悲鳴とともに飛び去った。\n 何が起きたのか考える暇もなく、封鎖が天から降り注ぐ。包囲が完成する前に、ここを突破しなければならない。"
        },
        Content_120202_11 = {
          ContentJP = "封鎖が完成する前に、あなたとカシュウは間一髪で飛び降り、執律閣の屋上から脱出した。\n あなたたちの行動により、城はすでに警戒態勢に入っている。狴犴と応天尉が巡回中だ。足取りが露見する前に、ここから逃げ出そう。"
        },
        Content_120202_12 = {
          ContentJP = "あなたたちの行動により、城はすでに警戒態勢に入っている。狴犴と応天尉が巡回中だ。\n 追い詰められたその時、ショウヨウセイが突如目の前に現れ、脱出を手助けすると約束した。"
        },
        Content_120202_13 = {
          ContentJP = "執律閣の屋上へ続く階段は、守衛が固く押さえている。\n 傍らのからくり人形が理由もなく何度も異音を立てていた。どうやら故障しているらしい。その不自然な騒ぎが、あなたにひらめきを与えた。"
        },
        Content_120202_14 = {
          ContentJP = "「裁定」の刻限だ。予定通り、執律閣へ向かおう。"
        },
        Content_120202_2 = {
          ContentJP = "執律閣の鐘が突如鳴り響いた。職人の話では、百年に一度あるかないかの珍事らしい。罪状が複雑で判別し難い者が現れた時にだけ、鐘は鳴るのだという。\n 人だかりに押し入って罪人の肖像を見たあなたは、思いもよらぬ見覚えのある顔に息を呑んだ——カシュウだ。"
        },
        Content_120202_3 = {
          ContentJP = "人だかりに押し入って罪人の肖像を見たあなたは、思いもよらぬ見覚えのある顔に息を呑んだ——カシュウだ。\n スノウと相談したいことがある。ここは人も多く会話するには不便だ。場所を移そう。"
        },
        Content_120202_4 = {
          ContentJP = "今朝からずっと、妙な違和感があなたを苛んでいる。カシュウを見つけることが、この謎を解く鍵になる——そんな予感がした。\n お触れには「裁定の儀、明日午の刻」（明日正午に裁定）とある。それまでに万全の準備を整えよう。"
        },
        Content_120202_5 = {
          ContentJP = "「裁定」の刻限だ。救出対象はいま、執律閣の屋上に拘束されている。\n だがシリュウから託された任務も忘れるな。まずは奉香の儀の物資を、執律閣内の受付係に渡そう。"
        },
        Content_120202_6 = {
          ContentJP = "「裁定」の刻限だ。救出対象はいま、執律閣の屋上に拘束されている。\n シリュウから託された任務を口実に、あなたたちは執律閣へ潜り込むことに成功した。屋上へ上がる方法を探そう。"
        },
        Content_120202_7 = {
          ContentJP = "執律閣の屋上へ続く階段は、守衛が固く押さえている。\n 突破口が見えず、ひとまずスノウと策を練ることにした。"
        },
        Content_120202_8 = {
          ContentJP = "からくり人形にちょっと細工を施し、守衛の注意を引きつけることに成功した。\n 誰にも気づかれないうちに、急いで執律閣の屋上へ忍び込もう。"
        },
        Content_120202_9 = {
          ContentJP = "幾多の困難を越え、あなたはついに執律閣の屋上へ辿り着いた——しかしちょうどその瞬間、太皓様が姿を現す。\n カシュウは太皓様と弁論したのち暗殺を試みるが、凡人の力では神明に及ばない。打ち飛ばされたカシュウが、あなたとスノウの存在を露呈させてしまった。\n 危急の瞬間、身を守るため、あなたはやむなく龍神の攻勢を受け止めた。"
        },
        Content_120203_1 = {
          ContentJP = "ショウヨウセイの助けで、あなたたちは普通の人は入れない「由来の里」へ逃げ込み、ようやく一息つけた。"
        },
        Content_120203_10 = {
          ContentJP = "ひと苦労の末、あなたたちはカシュウの言う「叔母さん」――スーイーという快活な少女と、ついに繋がることができた。\n 彼女に導かれ、あなたたちは流れ者の秘密基地——山外山へ辿り着く。"
        },
        Content_120203_11 = {
          ContentJP = "タンさんの話では、カシュウはあなたたちより先に山外山へ戻っている。合流しよう。"
        },
        Content_120203_12 = {
          ContentJP = "カシュウが外でやらかした大事件にスーイーは激怒していた。スーイーがカシュウを痛烈に叱り飛ばす場面を目撃する。カシュウはへらへらしながら助け舟を求めてくるが、あなたは……"
        },
        Content_120203_13 = {
          ContentJP = "対策を相談したのち、フーシュは先に皓京へ戻り、無窮蔵派の手掛かりを探しに行った。\n 山外山に滞在する間、あなたたちは雑務を手伝うことにした。ここを知る良い機会でもある。"
        },
        Content_120203_14 = {
          ContentJP = "タンさんは最近、足を痛めてしまった。スーイーについて行き、薬草を採って早く治せるようにしよう。\n 薬畑のそばで、邪魔をするクモハネカモメをどう懲らしめるかで言い争うシンとリクに出会った。目の前で腕前を見せてやろう。"
        },
        Content_120203_15 = {
          ContentJP = "クモハネカモメの騒ぎは片付いた。いつも薬畑を荒らす悪い鳥も、すっかり大人しくなった。さあ、薬草を採集しよう。"
        },
        Content_120203_16 = {
          ContentJP = "タンさんは最近、足を痛めてしまった。スーイーについて行き、薬草を採って早く治せるようにしよう。\n 薬草は採れた。タンさんに届けよう。"
        },
        Content_120203_17 = {
          ContentJP = "タンさんに薬を届けたついでに、天羅拒風儀の調整工具も受け取った。これは機枢派が開発した、大風九章の感応能力を遮断する装置だ。\n さあ、スーイーについて行って天羅拒風儀を調整しよう。"
        },
        Content_120203_18 = {
          ContentJP = "タンさんに薬を届けたついでに、天羅拒風儀の調整工具も受け取った。これは機枢派が開発した、大風九章の感応能力を遮断する装置だ。\n さあ、スーイーについて行って天羅拒風儀を調整しよう。"
        },
        Content_120203_19 = {
          ContentJP = "シンカンがあなたたちを呼び止め、少年・シュのことを案じていると告げた。最近のシュは武の鍛錬に取り憑かれ、どこか偏執的だという。あなたたちはシュの様子を見に行く約束をした。"
        },
        Content_120203_2 = {
          ContentJP = "ようやく危機を脱した。いったい何が起きたのか、カシュウと話そう。"
        },
        Content_120203_20 = {
          ContentJP = "洞窟で、自分を追い込みながら鍛錬を続けるシュを見つけた。いまの彼は人の忠告など聞く耳を持たない。スーイーは彼に「自分を証明する機会」を与えた。意地を張る少年を導いてやろう。"
        },
        Content_120203_21 = {
          ContentJP = "シュはあなたの前で十合も持たずに敗れた。さあ、改めて話をしよう。"
        },
        Content_120203_22 = {
          ContentJP = "山外山の迎え役を見つけたが、彼女は冷淡だった。\n カシュウの残した指示によれば、まず今日の「暗号」の動作を見つけなければ、迎え役と連絡を取れないという。"
        },
        Content_120203_23 = {
          ContentJP = "山外山の迎え役を見つけたが、彼女は冷淡だった。\n カシュウの残した指示によれば、まず今日の「暗号」の動作を見つけなければ、迎え役と連絡を取れないという。"
