        Content_200224_2 = {
          ContentJP = "どうやらテオは、下水道に棲みつく鼠たちに強い関心を抱いたようだ。彼の依頼で、あなたは一緒に下水道へ入り、鼠の巣を探すことに。"
        },
        Content_200224_3 = {
          ContentJP = "角を曲がった先で、目的の鼠を発見した。そのまま追跡し、巣の場所を突き止めよう。"
