        Event_WV_CiTiaoDes_01 = {
          ContentJP = "バトルスキル使用後5秒以内、武器ダメージを与えると範囲ダメージを追加で1回与える。このダメージは、ダメージを与えた武器の攻撃力が高いほどアップする。"
        },
        Event_WV_CiTiaoDes_02 = {
          ContentJP = "予備弾を消費した時、消費した予備弾数と同じスタック数の[シジル・1]を獲得する（累積不可）。遠隔武器ダメージを与えた時、[シジル・1]のスタック数をすべて消費し、消費したスタック数の回数分、範囲ダメージを与える。このダメージは遠隔武器攻撃力が高いほどアップする。"
        },
        Event_WV_CiTiaoDes_03 = {
          ContentJP = "与える武器ダメージは滞空時間が長いほどアップし、着地後にリセットされる。"
        },
        Event_WV_CiTiaoDes_04 = {
          ContentJP = "回避時、[シジル・2]を5スタック獲得する。最大10スタック。遠隔武器ダメージを与えた時、[シジル・2]を1スタック消費し、追加で1回範囲ダメージを与える。このダメージは遠隔武器攻撃力が高いほどアップする。"
        },
        Event_WV_CiTiaoDes_05 = {
          ContentJP = "武器ダメージで追加効果を発動した時、弾薬補給箱を1個ドロップする。弾薬補給箱を拾った時、自身を中心に1回大範囲ダメージを与える。このダメージは遠隔武器攻撃力が高いほどアップする。"
        },
        Event_WV_CiTiaoDes_06 = {
          ContentJP = "武器ダメージを与えた時、[シジル・3]を1スタック獲得する。最大30スタック。武器を切り替えた時、[シジル・3]を20スタック消費し、与える武器ダメージがアップする効果を獲得する。8秒間持続する。"
        },
        Event_WV_CiTiaoDes_07 = {
          ContentJP = "遠隔武器ダメージを与えた時、[シジル・4]を1スタック獲得する。最大40スタック。落下攻撃時、[シジル・4]のスタック数をすべて消費し、消費したスタック数に応じて落下攻撃のダメージをアップさせる。"
        },
        Event_WV_CiTiaoDes_08 = {
          ContentJP = "武器ダメージがクリティカルになると、[シジル・5]を1スタック獲得：クリティカル率が2.5%増加する。獲得時にすでに[シジル・5]が100スタックある場合、代わりに1回範囲ダメージを与える。このダメージは、ダメージを与えた武器の攻撃力が高いほどアップする。"
        },
        Event_WV_CiTiaoDes_09 = {
          ContentJP = "近接武器ダメージを与えた時、与える近接武器ダメージがアップする効果を1スタック獲得する、最大9999スタック。"
        },
        Event_WV_CiTiaoDes_10 = {
          ContentJP = "スライディング攻撃後、与えるスライディング攻撃ダメージがアップする効果を1スタック獲得する、最大9999スタック。"
        },
        Event_WV_CiTiaoDes_11 = {
          ContentJP = "弾倉を空にした後、与える近接武器ダメージがアップする効果を獲得する。10秒間持続する。"
        },
        Event_WV_CiTiaoDes_12 = {
          ContentJP = "溜め攻撃後、与える溜め攻撃ダメージがアップする効果を獲得する。5秒間持続する。この効果は溜め攻撃中の移動距離が長いほどアップする。"
        },
        Event_WV_CiTiaoDes_13 = {
          ContentJP = "与える武器ダメージがクリティカルになった時、遅延爆発する範囲ダメージを追加で1回与える。このダメージは、ダメージを与えた武器の攻撃力が高いほどアップする。"
        },
        Event_WV_CiTiaoDes_14 = {
          ContentJP = "近接武器の攻撃範囲はコンボLvが高いほどアップする。与える溜め攻撃ダメージはコンボLvが高いほど追加でアップする。"
        },
        Event_WV_CiTiaoDes_15 = {
          ContentJP = "落下攻撃後、次に非落下攻撃の近接武器ダメージを与えた時、[シジル・6]を1スタック獲得する。最大9999スタック。さらに1回範囲ダメージをを追加で与える。このダメージは[シジル・6]のスタック数が多いほどアップする。"
        },
