        No_Blueprints = {ContentJP = "なし"},
        NotInAnyGuild = {
          ContentJP = "まだ協会に加入していません"
        },
        NpcBiography_AgeText = {ContentJP = "年齢"},
        NpcBiography_Information_Aier = {
          ContentJP = "エルザは貴族出身で、知的で厳格な女性である。自分の立ち居ふるまいを厳しく律する彼女は、母親になると、娘のアニーを自分以上に優れた人間に育てようと、厳しくしつけた。しかしその期待とプレッシャーに耐えかねたアニーは家出してしまう。\nエルザは娘が不幸に巻き込まれているのではないかという不安を抱えながらも、必死でアニーを探し続けている。"
        },
        NpcBiography_Information_Aier_2 = {
          ContentJP = "エルザは貴族出身で、知的で厳格な女性である。自分の立ち居ふるまいを厳しく律する彼女は、母親になると、娘のアニーを自分以上に優れた人間に育てようと、厳しくしつけた。しかしその期待とプレッシャーに耐えかねたアニーは家出してしまう。"
        },
        NpcBiography_Information_Aima = {
          ContentJP = "今日のエマは心ここにあらずだった。アイスレイク城を一歩も出たことはないが、広場の記念碑には50回以上も祈りを捧げてきた。ほとんどの場合、まじめな態度を保っているのだが、時々、本当にごくたまに、この延々と繰り返される儀式から逃れ出して、広場の向かい側にある小さなテントへ駆け込みたくなる。角の生えたおばあさんが今度はどんな新しいものを作っているのか気になって仕方がないのだ。"
        },
        NpcBiography_Information_Alice_1 = {
          ContentJP = "記憶を失った少女。つい最近、優しい医者に助けられ、アイスレイク城で療養中。今は必死に、自分が誰だったのか思い出そうとしている。"
        },
        NpcBiography_Information_Alice_2 = {
          ContentJP = "冒険好きな少女、アリス。\n常に万全の準備をして冒険に挑むアリスだが、ある日、予期せぬ吹雪に遭い、雪山で遭難してしまった。\n家出少女のアニーと出会い、吹雪の中で運命を共にしたが、アニーは自分の命が長くないことを悟って、アリスに自分の厚着を譲ってくれた。そのおかげでアリスは雪山から無事に生還する。\n救助されてしばらくは記憶を失っていたが、今はすべてを思い出し、アニーの善意を胸に、新しい人生を歩み始める。"
        },
        NpcBiography_Information_Alice_3 = {
          ContentJP = "山で吹雪に巻き込まれ、記憶を失った少女。\n最初は混乱していたが、次第に自分が「アニー」であることを受け入れ、母親であるエルザとの再会を心待ちにしている。\n二人にはきっと幸せな結末が待っているだろう。"
        },
        NpcBiography_Information_Anuo = {
          ContentJP = "アーノルドは幸運な子供だった。カロン族の子供でありながら、孤児院で無事に育つことができたのだから。しかし同時に、彼は不運でもあった。孤児院の子供たちが増えるにつれ、まだ幼い年齢で追い出されることになり、生きるために知恵を絞らねばならなかったのだ。\n\nカロン族はソラより強靭な体を持つとはいえ、子供にとってアイスレイク城の夜の冷え込みは命を奪いかねない。孤児院を出てからというもの、アーノルドは極寒の夜を一日また一日とどう生き延びるか、必死に考え続けた。\n\nアーノルドは持ち金をすべて商品に換え、劇場の前で売り始めたものの、商売は振るわなかった――アイスレイク城の住民のほとんどは演劇に関心がなく、ただ一人、気取った物言いの貴族の旦那様だけが頻繁に足を運んでくれた。アーノルドはその旦那様のことを悪くは思っていない。いつも買い物をしてくれるからだ。しかし、発酵飲料だけは一度も買わないので、思い切って訊ねてみると、華麗な修辞法と回りくどい言葉のなかから、どうやら彼は発酵飲料に極端に弱く、口をつけただけで眠り込んでしまうのだと理解できた。\n\nこの常連客のおかげで、アーノルドはしばらくの間、何とか暮らすことができた。だが、一段と寒さの厳しい冬が訪れ、越冬用の燃料を買うだけの金もない状況に追い込まれた。そんな時、彼は大胆な考えを思いついた……\n\nアーノルドは貴族の旦那様の跡をつけ、きちんと閉まっていない窓から屋内に忍び込んだ――旦那様は落ちぶれた小貴族で、召使いもおらず、暖炉の火も弱々しかったが、外の凍てつく寒さに比べれば、まるで春のような暖かさだった。\n\nアーノルドはそっと台所に忍び込み、水差しにほんの少しだけアルコール飲料を混ぜた。そして、貴族の旦那様が劇場から戻って一口飲み、すっかり眠り込むのを待つ。その後は、暖炉の温もりを存分に楽しめるはずだった……"
        },
        NpcBiography_Information_Bake = {
          ContentJP = "バック氏は、話し方も行動もまるで詩を詠むかのような男だ。誰でも心地よいことに惹かれるものだが、彼の文学と芸術への愛は生活の隅々にまで染みわたり、明らかにやりすぎなところがある。\n\n酒場の常連たちはよく噂している。バック氏は没落した小貴族で、遺産のおかげでなんとか食事と暖かい部屋を維持できているが、もしその遺産がなければ、文学の知識以外に何の取り柄もない彼はきっと橋の下で寝ることになるだろうと。\n\nこれは的確な評価だろう。得意な創作活動でさえ、これといった成果は上げられていない。ヘゴン劇場に送り続けている脚本は、いまだかつて上演されたことがない――おそらく永遠にその日は来ないだろう。彼は劇場のまわりをさまよいながら、秋の落ち葉を題材にした詩を口ずさむばかりだ。\n\n最近、バック氏は「月光」「墓地」「引き裂かれた恋人たち」「すれ違う時間」そして「愛と死」をテーマにした悲劇を書いている。創作に心を注ぎすぎたせいか、あるいは劇場からの度重なる拒絶で心が折れたせいか、妙な思い込みに取り憑かれてしまった。部屋で足音が聞こえたり、不思議な匂いがするという。しかも、そんな不可解な現象に包まれるたびに突然眠りに落ちてしまい、夜の創作の時間を無駄にしているというのだ。\n\n実際のところ、財産が失われたわけでもなく、夜更かしをしなくなっただけ――むしろ健康的な変化とさえ言える。それなのにバック氏は憤慨し、あちこちで「霊感泥棒」を捕まえる手助けを求めて回っているが、誰も相手にしていない。気でも狂った厄介な依頼主だと思われているうえ、報酬もわずかだからだ。バック氏は、自分の戯曲は必ず帝都最大の劇場で成功をおさめ、その暁には「霊感泥棒」を捕まえた恩人を次の作品に登場させ、後世に名を残すと約束しているが……誰も信じる者はいない。"
        },
        NpcBiography_Information_Beiguanjiaojiao = {
          ContentJP = "彼女は悲観主義者で、口癖は「世界の終わりは近い」。帝国の情勢は日に日に危険になり、まもなく戦争が起こり、大陸全土の人々が命を失い、世界は滅ぶと信じている。酒場に通っては酒に溺れ、気晴らしにしているが、医者の診断では「頭の病気」らしく、誰も真に受けてはいない。"
        },
        NpcBiography_Information_Beilinda = {
          ContentJP = "ベリンダは裏路地に小さなテントを張り、そこで絶望しているカロン族たちに亡くなった家族の言葉を伝え、未来への道を示そうとしている。大勢のカロン族がここで午後を過ごし、ベリンダは祖母のように彼らの悩みに耳を傾け、心の痛みを癒している。しかし受け取るのはほんの少しの小銭だけで、非常に貧しい生活を送っている。\n\n貧しい暮らしにもかかわらず、ベリンダはいつも小さなアクセサリーで身を飾っている。彼女の器用な手は、割れたガラスや針金、誰かが捨てた布の切れ端さえも、見事な工芸品へと生まれ変わらせる。もしあなたがその作品を欲しいと言えば、ためらうことなく譲ってくれるだろう――つい先日も、小さな女の子の人形を誰かに贈ったばかりだ。\n\n今日のベリンダには客がいない。彼女はテントから顔を出し、誰かの訪問を待っているようだ。"
        },
        NpcBiography_Information_Blue = {
          ContentJP = "パーガトリー島出身の老人。\nかつて未来への憧れを抱いて、先祖代々の掟を破って島を離れたようだ。しかし現実は厳しく、詐欺まがいの商売で糊口をしのいでいる。"
