        },
        READSERIES_1127 = {
          ContentJP = "落とした紙片・フラワー駅"
        },
        READSERIES_DESC_1039 = {
          ContentJP = "書類の山から一つのファイルを見つけ出した。表紙には子どもたちの写真が貼られている。開くと、彼らが「ヒュプノスの家」で過ごした日々の記録が、克明につづられていた。"
        },
        READ_DESC_2000001 = {
          ContentJP = "石像の台座に刻まれた文字はすでに風化してぼやけているが、おそらくは神への賛美だろう。"
        },
        READ_DESC_2000002 = {
          ContentJP = "黄ばんで少し破損している錬金術の書。中には端正な字の注釈が大量に記載されている。"
        },
        READ_DESC_2000003 = {
          ContentJP = "筆者不明の日記。端正な字で書かれてあるが、破れているので一部まともに読めない。"
        },
        READ_DESC_2000004 = {
          ContentJP = "筆者不明の日記。端正な字で書かれてあるが、破れているので一部まともに読めない。"
        },
        READ_DESC_2000005 = {
          ContentJP = "筆者不明の日記。端正な字で書かれてあるが、破れているので一部まともに読めない。"
        },
        READ_DESC_2000006 = {
          ContentJP = "断続的な録音ファイルには、サイキとヘンリックの最後の会話が記録されている。"
        },
        READ_DESC_2000007 = {
          ContentJP = "歴史ある医学の大著で、さまざまな病気の原因、症状、治療法が詳細に記録されている。治療法が未記入の部分も多いが、表紙にある「どんな病気も、いずれは人類によって克服される」という言葉の通り、これらの空白は何代にもわたる医師や学者の手によって必ず埋められるだろう。"
        },
        READ_DESC_2000008 = {
          ContentJP = "異国風の装丁が施された書物。何度も読み込まれたため非常に古びており、軽くめくるだけで崩れてしまいそうだ。内容から、薬学に関する本だとわかる。"
        },
        READ_DESC_2000009 = {
          ContentJP = "引き出しに入っている手紙は豪華に装丁されている。宛名はヘンリック‐エセルレッド。"
        },
        READ_DESC_2000010 = {
          ContentJP = "机の上に置かれた手紙。なんらかの理由で投函されてない。"
        },
        READ_DESC_2000011 = {
          ContentJP = "家族宛の手紙らしいが、後半部分は文字が水でにじんでいて読みとれない。しかし、この手紙がホコリまみれで放置されていることや、ヒュプノスの家の存在が、当時のヘンリックの選択を雄弁に物語っている。"
        },
        READ_DESC_2000012 = {
          ContentJP = "ありふれたタイトルの連載小説。数十年前のヒュペリアとエリュシオンの戦争を舞台にヒュペリアの少年が冒険を繰り広げるストーリーが、帝国の若者のあいだで人気を博している。"
        },
        READ_DESC_2000013 = {
          ContentJP = "この日記の持ち主はは長い間野外で生活しているため、ほとんどのページが汚れて読みにくいが、最近書かれた部分は比較的読みやすい。"
        },
        READ_DESC_2000014 = {
          ContentJP = "テオの観察日記。環境、植物、動物、人間などあらゆる事柄が記録されている。"
        },
        READ_DESC_2000015 = {
          ContentJP = "テオの観察日記。環境、植物、動物、人間などあらゆる事柄が記録されている。"
        },
        READ_DESC_2000016 = {
          ContentJP = "テオの観察日記。環境、植物、動物、人間などあらゆる事柄が記録されている。"
        },
        READ_DESC_2000017 = {
          ContentJP = "アニーが母親に宛てた独白の手紙。長い間ポケットに入れていたため、手紙の端が擦り切れているが、読むには問題ない。"
        },
        READ_DESC_2000018 = {
          ContentJP = "グレーム鉱山で見つかった日記。持ち主が慌てて残したものと思われる。文面には持ち主の後悔や、いくつかの真偽不明の噂が記されている。"
        },
        READ_DESC_2000019 = {
          ContentJP = "グレーム鉱山の奥深くで発見された日記。40年にわたる年月が記され、乱れた筆跡の中には若い男性の純粋で激しい願いが読み取れる。"
        },
        READ_DESC_2000020 = {
          ContentJP = "壁に深く刻まれた文字の拓本。指で触れると刻んだ人の怒りがかすかに感じられる気がする。"
        },
        READ_DESC_2000021 = {
          ContentJP = "下水道の壁の隙間からかろうじて読み取れた文字の拓本。下水道にいる誰かに関連しているようだ。"
        },
        READ_DESC_2000022 = {
          ContentJP = "下水道の壁の隙間からかろうじて読み取れた文字の拓本。下水道にいる誰かに関連しているようだ。"
        },
        READ_DESC_2000023 = {
          ContentJP = "誇張された内容のチラシで、廃鉱の荒廃した光景を自分の目で見なければ、ほんの少しでも信じてしまうかもしれない。 このチラシを持ち帰ることは、潜在的な詐欺の被害者を救うことに繋がる。 \n箱の中の「餌」は、善行を重ねた報酬だと思って、堂々と受け取ろう。"
        },
        READ_DESC_2000024 = {
          ContentJP = "水に浸されたらしいくしゃくしゃの手紙。封筒には受取人の名前しか書かれていない。"
        },
        READ_DESC_2000025 = {
          ContentJP = "古びた紙だが、損傷はまったくなく、大切に保管されていたようだ。 \n表紙には、灰色の長髪を持つ女性の肖像が描かれており、彼女の左目には純白の花が咲いている。 \n背表紙の中央には「フォーセイクン同盟」のマークがあり、その下には小さな文字で「自由が私たちの未来を導きますように」と書かれている。"
        },
        READ_DESC_2000026 = {
          ContentJP = "1年半前に書かれた申請書。申請は承認されなかった。"
        },
        READ_DESC_2000027 = {
          ContentJP = "紙片のやり取りでかわされた会話が記録されている。紙片の破損状況から、最近のものではないことがわかる。"
        },
        READ_DESC_2000028 = {
          ContentJP = "日記の内容から、フォーセイクン同盟の規律が緩んでいる様子がうかがえる。"
        },
        READ_DESC_2000029 = {
          ContentJP = "2年前に書かれた申請書。申請は承認されなかった。"
        },
        READ_DESC_2000030 = {
          ContentJP = "要塞の兵士たちが唯一祝うことを許された祭日。"
        },
        READ_DESC_2000031 = {
          ContentJP = "真新しい避難通知。形式から帝国の文書ではないことが分かる。"
        },
        READ_DESC_2000032 = {
          ContentJP = "ロンザ要塞の模擬戦場コントロールパネルに記録された対戦記録。帝国兵士の模擬対戦の成績が、規則正しく記録されており、各部隊の戦闘中のパフォーマンスに基づいて、適切な評価と提案がなされている。\nしかし、最後の数行の記録が突然大きく変化しており、明らかに帝国軍の手によるものではなく、フォーセイクン同盟の者が記したものであることがわかる。"
        },
        READ_DESC_2000033 = {
          ContentJP = "戦車の貯蔵箱の奥深くに、大事にしまわれた非公式な軍用犬の名簿らしきものがあった。どうやら、軍犬を管理していた帝国の兵士が記録したもののようだ。\n最後の部分には水の跡がついており、少し読みにくくなっている。"
        },
        READ_DESC_2000034 = {
          ContentJP = "緊急治療の記録で。不必要な形式や言い回しは省かれ、負傷者の状態と受けた応急処置が簡潔に記録されている。\n医療物資の残量を記録したページでは、数字が減るにつれて字が乱れ、筆者の不安と焦りが紙面からはっきりと伝わってくる。"
        },
        READ_DESC_2000035 = {
          ContentJP = "フォーセイクン同盟の新メンバーに関する会話記録。"
        },
        READ_DESC_2000036 = {
          ContentJP = "フォーセイクン同盟のメンバーが残した日記。内容から判断すると、この日記の持ち主は治療師のようだ。"
        },
        READ_DESC_2000037 = {
          ContentJP = "机の上に手紙が置かれている。すでに開封されており、きちんとした筆跡で書かれた宛名はヘンリック‐エセルレッド。"
        },
        READ_DESC_2000038 = {
          ContentJP = "数通の督促状が机の上に散乱している。どの手紙もヘンリックに借金返済を急かす内容だ。かなり前から「ヒュプノスの家」の経営が立ち行かなくなっているのは明らかだ。"
        },
        READ_DESC_2000039 = {
          ContentJP = "剥がされた薬瓶のラベルが一束。すべてに「鎮静剤」の文字が印刷されている。そのうちの一枚、ラベルの裏には誰かが力を込めて走り書きした文字が残されていた。"
        },
        READ_DESC_2000040 = {
          ContentJP = "一枚の薄い便せんに、詩が書かれている。"
        },
        READ_DESC_2000041 = {
          ContentJP = "書類の山から一つのファイルを見つけ出した。表紙にはサイキの写真が貼られている。開くと、彼女が「ヒュプノスの家」で過ごした日々の記録が、克明につづられていた。"
        },
        READ_DESC_2000042 = {
          ContentJP = "書類の山から一つのファイルを見つけ出した。表紙にはエリーザの写真が貼られている。開くと、彼女が「ヒュプノスの家」で過ごした日々の記録が、克明につづられていた。"
        },
        READ_DESC_2000043 = {
          ContentJP = "書類の山から一つのファイルを見つけ出した。表紙にはハンターの写真が貼られている。開くと、彼が「ヒュプノスの家」で過ごした日々の記録が、克明につづられていた。"
        },
        READ_DESC_2000044 = {
          ContentJP = "すでに倒産した雑誌社が出版した怪談集。帝国の錬金術と武力至上主義の時代背景の中、人々が余談として笑い飛ばすネタにすらならないほど忘れ去られている。\n「夜10時に決して乗ってはいけない無人車」「アイスレイク城には真っ黒な猫などいない」といった都市伝説が収録されており、本編では「人類は飼育されたアリにすぎない」と信じる人物の物語が描かれている。"
        },
        READ_DESC_2000045 = {
          ContentJP = "中央に「フォーセイクン同盟」の紋章が描かれた羊皮紙。何者かにぐしゃぐしゃにされ、乱暴に下水道に捨てられていた。下にはこう書かれている――「復讐が我らの道を導かんことを」"
        },
        READ_DESC_2000046 = {
          ContentJP = "多くの裏方スタッフが記録した準備リスト。過去半月分の小道具の出入りが詳細に記録されている。"
        },
        READ_DESC_2000047 = {
          ContentJP = "純金で作られた勲章。一枚の黄金から成るその輝きは、帝国への卓越した貢献を称える証だ。添えられた賞賛の書状によれば、この勲章は並外れた功績を上げた軍人のみに授与されるという。"
        },
        READ_DESC_2000048 = {
          ContentJP = "ガラクタの下に埋もれていた一枚の古びた新聞――そこには、かつて起きた悲劇的な事件が記されていた。"
        },
        READ_DESC_2000049 = {
          ContentJP = "リズムが抜粋した、二年前にガレア劇場で起きた乱闘事件の記録。"
        },
        READ_DESC_2000050 = {
          ContentJP = "口調からして、ブルース・フィッシャーが書いた日記と思われる。リズムとの日々の出来事がびっしりと綴られ、ついには裏面にまで書き込まれ、本の隅々まで使い尽くされている。"
        },
        READ_DESC_2000052 = {
          ContentJP = "下水道で見つかった小型手帳。汚れと血でページ全体が染まっており、もとの内容を判読するのは非常に困難だ。"
        },
        READ_DESC_2000053 = {
          ContentJP = "（劇団の隅で見つかった古い脚本。表紙には「パシファル」の手書きメモがあり、彼が何度も読み返し、出演を夢見ていた演目と思われる。）\nエリュシオン礼賛会の北西、岬の先にかつて「ヤシュニア公国」と呼ばれる国があった。ヒュペリア帝国と海を隔てて向かい合い、商業で栄え、礼賛会と帝国の間を巧みに立ち回ったが、最終的には礼賛会に併呑され、三百年以上前に滅亡した。ヤシュニアは小国ながら、その存続のために公爵家は多くの努力を重ねた。宮廷の血なまぐさい陰謀や政治的暗殺もあったが、吟遊詩人たちはこの国を舞台に数々の劇を創作した。現在その領土はすべて礼賛会に組み込まれているが、宮廷暗殺の描写を禁じる帝国ですら、「礼賛会の邪悪な過去を暴く作品」として、これらの劇の上演を許している。壮大な歌と華麗な戦闘演出で知られる『紅葉返り討ち秘話』は、その中でも特に人気のある演目である。"
        },
        READ_DESC_2000057 = {
          ContentJP = "銀燭祭りのときに歌われる歌謡、銀燭祭りの起源の伝説を語っている：ヒュペリア帝国の初代皇帝ディズ1世の弟ソラヌスはカロン族に殺されたが、ディズ1世はカロン族を征服した後、寛容と平和を選び、宴を開いた。\n この宴が今の銀燭祭りの源だと言われている。"
        },
        READ_DESC_2000067 = {
          ContentJP = "怒りの感情すら伝わるほど乱雑な筆跡の手書きビラ。大声で叫んでいるかのようで、その内容はすべて「銀燭祭り賛歌」の否定であり、全く逆の物語を語っている。"
        },
        READ_DESC_2000068 = {
          ContentJP = "アスフォデロスのお酒メニュー。どうぞご自由に召し上がれ、どの酒も香り豊かで、飲み終わればまた欲しくなるわよ。"
        },
        READ_DESC_2000069 = {
          ContentJP = "フォーセイクン同盟の上層部についての噂。真偽は不明だが、暇つぶしの読み物としては悪くない。"
        },
        READ_DESC_2000070 = {
          ContentJP = "イーザーの学者コムネナが著した歴史書。かなり難解で、しかもヒュペリア帝国の公式歴史と少し食い違っているため、あまり見かけない。本屋で五年に一度売れる程度の、実用性より装飾性が高い本。"
        },
        READ_DESC_2000072 = {
          ContentJP = "初期の燭陰の禍から生き残った者の口述記録。煙津渡の山中で暮らす一人の農夫から聞き取ったもの。"
        },
        READ_DESC_2000073 = {
          ContentJP = "書き直しの跡だらけの古びた本。筆者が実例を大量に挙げ、対話で優位に立つ方法を説いているようだが、今では誰かに放置されたままになっている。"
        },
        READ_DESC_2000074 = {
          ContentJP = "機枢派を宣伝するための歌と思われるが、歌詞は意味不明で一行も理解できない。文字を見るだけで、誰かの断末魔の叫びが頭に響くかのようだ。"
        },
        READ_DESC_2000075 = {
          ContentJP = "いい加減なタイトルの長編連載小説。「チョウツエエエ」という名の少年が龍淵の上卿に選ばれたことから始まる冒険譚で、華胥の若者たちに大人気。"
        },
        READ_DESC_2000076 = {
          ContentJP = "無数の印が押された豪華な装丁の水墨画。華胥の山水が描かれており、落款には短い詩が添えられている。よく見ると、その一部の文字に妙な違和感がある。"
        },
        READ_DESC_2000077 = {
          ContentJP = "「風伯」と呼ばれた老人が語ったとされる幻想物語。面白い内容ゆえ後世に編纂され書籍となった。大人の中には不適切な描写を指摘する者もいるが、華胥では子ども向け読物として広く流行している。"
        },
        READ_DESC_2000078 = {
          ContentJP = "黒龍祭壇付近で捨てられていた作者不明の手記。文字の一部はすでに判読できない。筆者がここで遭遇した出来事が細かく綴られており、真相を追う者がどれほどの絶望の中で書き残したのか想像を誘う。"
        },
        READ_DESC_2000079 = {
          ContentJP = "一枚のメモ。荷の積み下ろしの合間に走り書きされたものらしい。"
        },
        READ_DESC_2000080 = {
          ContentJP = "文字は乱れ、消し跡も多く残る。筆者の焦りがそのまま伝わってくる。扉には「風」の字が署名として記されている。"
        },
