        RESOURCE_DESC_3000002 = {
          ContentJP = "汚れた薄手の服に、手のひらサイズの日記が包まれている。表紙の「アリス」という名前が判読可能だが、そのほかのほとんどの内容は汚れで読めない。最近書かれたらしい文字だけが辛うじて判読可能だ。"
        },
        RESOURCE_DESC_3000003 = {
          ContentJP = "古い冒険小説。主人公と彼の痩せ馬が城を攻め落とし、財宝を手に入れる物語。"
        },
        RESOURCE_DESC_3000004 = {
          ContentJP = "針金で作られたベレニカの横顔の肖像。特徴を正確に捉えている。"
        },
        RESOURCE_DESC_3000005 = {
          ContentJP = "帝国軍標準装備の医療キット。戦場での応急処置に対応するため、さまざまな止血薬や鎮痛剤が含まれているが、重傷にはあまり効果がない。"
        },
        RESOURCE_DESC_3000006 = {
          ContentJP = "アヴァールが大切に身に着けている写真。彼と幼少期のダフネが一緒に写っている。黄ばんで古い写真だが、二人の輝く笑顔は色あせることなく、まぶしく輝いている。"
        },
        RESOURCE_DESC_3000007 = {
          ContentJP = "アヴァールが大切に身に着けている写真。彼と幼少期のダフネが一緒に写っている。二人の輝く笑顔はどす黒い血痕に覆われてしまっている。"
        },
        RESOURCE_DESC_3000008 = {
          ContentJP = "サイキからもらった花。彼女の手のひらのぬくもりがまだ残っているようだ。"
        },
        RESOURCE_DESC_3000009 = {
          ContentJP = "簡単な処方箋だが、その裏面には帝国の人々には見せることができない危険な文字がびっしりと書かれている。"
        },
        RESOURCE_DESC_3000010 = {
          ContentJP = "フェイからの贈り物。それは彼女が自ら描いた、あなたの「肖像画」――もっとも、あなたの目には、赤と白が入り混じった色の塊は、かろうじて人の形をとどめているだけで、性別さえ判然としない。それでも、彼女が「これはあなたの肖像だ」と言うのであれば、そうなのだろう。内城の人々の美意識を理解するには、かなりのセンスと感性が求められるようだ。"
        },
        RESOURCE_DESC_3000011 = {
          ContentJP = "精巧に作られた鍵。なぜか見覚えがあるが、その理由は思い出せない。おそらく、いつかふさわしい瞬間が訪れれば、この鍵は長い間眠っていた秘密を、明らかにするのだろう。"
        },
        RESOURCE_DESC_3000018 = {
          ContentJP = "油絵制作に適した白い絵の具。"
        },
        RESOURCE_DESC_3000019 = {
          ContentJP = "金庫の中に保管されていた鎮痛剤。"
        },
        RESOURCE_DESC_3000020 = {
          ContentJP = "煙突清掃人の社員証。"
        },
        RESOURCE_DESC_3000021 = {
          ContentJP = "小切手の束。一枚につき金貨五枚の価値がある。"
        },
        RESOURCE_DESC_3000022 = {
          ContentJP = "医療用の止血鉗子。"
        },
        RESOURCE_DESC_3000023 = {
          ContentJP = "平べったい球状の金属製酒壺。"
        },
        RESOURCE_DESC_3000024 = {
          ContentJP = "密輸された綿入り衣類。中の綿の半分はすでに抜き取られている。"
        },
        RESOURCE_DESC_3000025 = {
          ContentJP = "錬金術師たちがよく使う薬。鼻をつく酸っぱい匂いがする。"
        },
        RESOURCE_DESC_30001 = {
          ContentJP = "「移転モジュール」の製造に用いられる材料。ゲル状で純度が高く、水に溶けやすいが、高温で活性を失うため、保存がむずかしい。それでも、持ち運ぶ価値は十分にある。"
        },
        RESOURCE_DESC_30002 = {
          ContentJP = "「武器移転モジュール」の製造に用いられる材料。特別に加工された磁石で、金属部品によって異なる振動を引き起こす。熟練者はその振動から、武器の微妙な異常を発見できる。"
        },
        RESOURCE_DESC_3001 = {
          ContentJP = "フィーリングシステムのチェックに失敗した後、再度やり直す時に使用できる。\n人づきあいに波風がつきものだが、挫けずに何度でも挑戦すればいいのだ。"
        },
        RESOURCE_DESC_3002 = {
          ContentJP = "ジェネモンの大好物。ジェネモンの給餌に使用できる。\nその名の通り、もしジェネモンが話せるなら、きっと「すごい、うまうま！」と叫ぶだろう。"
        },
        RESOURCE_DESC_3003 = {
          ContentJP = "ジェネモンの大好物。ジェネモンの給餌に使用できる。\nその名の通り、もしジェネモンが話せるなら、きっと「すごい、うまうま！」と叫ぶだろう。"
        },
        RESOURCE_DESC_3004 = {
          ContentJP = "ジェネモンの大好物の栄養剤。ジェネモンのレベルアップに使用できる。使用すると経験値100アップする。\nその名の通り、もしジェネモンが話せるなら、きっと「うまい！」と叫ぶだろう。"
        },
        RESOURCE_DESC_3005 = {
          ContentJP = "ジェネモンの大好物の栄養剤。ジェネモンのレベルアップに使用できる。使用すると経験値300アップする。\nその名の通り、もしジェネモンが話せるなら、きっと「すごい、うまい！」と叫ぶだろう。"
        },
        RESOURCE_DESC_3006 = {
          ContentJP = "ジェネモンの大好物の栄養剤。ジェネモンのレベルアップに使用できる。使用すると経験値1000アップする。\nその名の通り、もしジェネモンが話せるなら、きっと「すごい、めっちゃうまい！」と叫ぶだろう。"
        },
        RESOURCE_DESC_3007 = {
          ContentJP = "ジェネモンの大好物のドリンク。ジェネモンの限界突破に使用できる。\nその名の通り、もしジェネモンが話せるなら、きっと「すごい、うまい！」と叫ぶだろう。"
        },
        RESOURCE_DESC_3008 = {
          ContentJP = "ジェネモンたちが大好きな食べ物。与えると変異体ジェネモンに変わる。ジェネモンにとっては、変異しちゃうほど美味しいらしい。"
        },
        RESOURCE_DESC_301 = {
          ContentJP = "所持していると乗り物に搭乗でき、アイスレイク城エリア内で飛行できる。"
        },
        RESOURCE_DESC_3010 = {
          ContentJP = "キャラクターの功利ステータスを上げるのに使えます"
        },
        RESOURCE_DESC_30101 = {
          ContentJP = "いろいろな原料を調合して作られた染料ダクリ湖のような色に染めることができる。"
        },
        RESOURCE_DESC_30102 = {
          ContentJP = "いろいろな原料を調合して作られた染料。海の塩のような色に染めることができる。"
        },
        RESOURCE_DESC_30103 = {
          ContentJP = "いろいろな原料を調合して作られた染料。木の枝先のような色に染めることができる。"
        },
        RESOURCE_DESC_30104 = {
          ContentJP = "いろいろな原料を調合して作られた染料。エンドウ豆のような色に染めることができる。"
        },
        RESOURCE_DESC_30105 = {
          ContentJP = "いろいろな原料を調合して作られた染料。砂丘のような色に染めることができる。"
        },
        RESOURCE_DESC_30106 = {
          ContentJP = "いろいろな原料を調合して作られた染料。赤土のような色に染めることができる。"
        },
        RESOURCE_DESC_30107 = {
          ContentJP = "いろいろな原料を調合して作られた染料。ルージュのような色に染めることができる。"
        },
        RESOURCE_DESC_30108 = {
          ContentJP = "いろいろな原料を調合して作られた染料。カラスのような色に染めることができる。"
        },
        RESOURCE_DESC_30109 = {
          ContentJP = "いろいろな原料を調合して作られた染料。雷雨のような色に染めることができる。"
        },
        RESOURCE_DESC_3011 = {
          ContentJP = "キャラクターの道徳ステータスを上げるのに使えます"
        },
        RESOURCE_DESC_30110 = {
          ContentJP = "いろいろな原料を調合して作られた染料。天の河のような色に染めることができる。"
        },
        RESOURCE_DESC_30111 = {
          ContentJP = "いろいろな原料を調合して作られた染料。麦の穂のような色に染めることができる。"
        },
        RESOURCE_DESC_30112 = {
          ContentJP = "いろいろな原料を調合して作られた染料。任意の基本染料の色に染めることができる。"
        },
        RESOURCE_DESC_30113 = {
          ContentJP = "いろいろな原料を調合して作られた染料。メープルシロップのような色に染めることができる。"
        },
        RESOURCE_DESC_30114 = {
          ContentJP = "いろいろな原料を調合して作られた染料。ココアのような色に染めることができる。"
        },
        RESOURCE_DESC_30115 = {
          ContentJP = "いろいろな原料を調合して作られた染料。碧い波のような色に染めることができる。"
        },
        RESOURCE_DESC_30116 = {
          ContentJP = "いろいろな原料を調合して作られた染料。蒼い松のような色に染めることができる。"
        },
        RESOURCE_DESC_30117 = {
          ContentJP = "いろいろな原料を調合して作られた染料。桃の花のような色に染めることができる。"
        },
        RESOURCE_DESC_30118 = {
          ContentJP = "いろいろな原料を調合して作られた染料。髪をさまざまな色に染めることができる。"
        },
        RESOURCE_DESC_30119 = {
          ContentJP = "いろいろな貴重な原料を調合して作られた染料。髪をさまざまな色に染めることができる。"
        },
        RESOURCE_DESC_3012 = {
          ContentJP = "キャラクターの才知ステータスを上げるのに使えます"
        },
        RESOURCE_DESC_3013 = {
          ContentJP = "キャラクターの共感ステータスを上げるのに使えます"
        },
        RESOURCE_DESC_3014 = {
          ContentJP = "キャラクターの混沌ステータスを上げるのに使えます"
        },
        RESOURCE_DESC_3015 = {
          ContentJP = "華胥の伝説には、釣り人の中で赫々たる名を馳せた人物がいる。本名はとうに定かではなく、民間では「釣りの太公」と呼ばれている。噂では、「餌を付けなくてもバンバン釣れる」という技を持つという。\n その釣り技を学ぶのは現実的ではないが、機枢の職人たちに頼んで彼の釣り竿を模した一本を作らせるくらいなら簡単だ。"
        },
        RESOURCE_DESC_3016 = {
          ContentJP = "錬金術師たちが作り上げた魔の楔増幅装置。\n 資材の乏しい前線では、限られた材料で魔の楔の無尽蔵の力をいかに引き出すかが、長らく錬金術師たちを悩ませてきた。"
        },
        RESOURCE_DESC_3017 = {
          ContentJP = "キャラクターの華胥での功利ステータスを上げるのに使えます"
        },
        RESOURCE_DESC_3018 = {
          ContentJP = "キャラクターの華胥での道徳ステータスを上げるのに使えます"
        },
        RESOURCE_DESC_3019 = {
          ContentJP = "キャラクターの華胥での才知ステータスを上げるのに使えます"
        },
        RESOURCE_DESC_302 = {
          ContentJP = "所持していると乗り物に搭乗でき、煙津渡エリア内で飛行できる。"
        },
        RESOURCE_DESC_3020 = {
          ContentJP = "キャラクターの華胥での共感ステータスを上げるのに使えます"
        },
        RESOURCE_DESC_3021 = {
          ContentJP = "キャラクターの華胥での混沌ステータスを上げるのに使えます"
        },
        RESOURCE_DESC_303 = {
          ContentJP = "所持していると乗り物に搭乗でき、フラワー駅エリア内で飛行できる。"
        },
        RESOURCE_DESC_40001 = {
          ContentJP = "救急箱の必須品、瓶入りの薬剤。病気や痛みで意識が薄れた時などに使用すれば、体力を取り戻し、一時的に意識がはっきりする。"
        },
        RESOURCE_DESC_40003 = {
          ContentJP = "弾丸がいっぱいに詰め込まれた補給箱。戦場における命の源、または死への招待状である。"
        },
        RESOURCE_DESC_4001 = {
          ContentJP = "個人活躍度は、協会メンバーが一週間どれくらい活躍したかを示します。協会イベントに積極的に参加すると、さまざまな報酬を獲得できます"
        },
        RESOURCE_DESC_40014 = {
          ContentJP = "気つけ薬は救急箱に欠かせない必需品。華胥の合香師によって改良され、本来の効能を保ちながら、より芳香豊かになっている。"
        },
        RESOURCE_DESC_4002 = {
          ContentJP = "グリニッジ考古協会には多数の分会が属しており、協会活躍度は各協会の直近の実績を評価する重要な指標となります"
        },
        RESOURCE_DESC_4003 = {
          ContentJP = "グリニッジ考古協会の特別許可証。これを所持していれば協会を設立できます"
        },
        RESOURCE_DESC_4004 = {
          ContentJP = "名声は協会の影響力を示します。協会名声を貯めて、協会レベルを上げましょう"
        },
        RESOURCE_DESC_4005 = {
          ContentJP = "協会の日常運営には資金が欠かせません。資金を所持していれば、対応する協会建設を行えます"
        },
        RESOURCE_DESC_4006 = {
          ContentJP = "協会はキョウンの理念を取り入れており、活躍したメンバーはみな相応の表彰を受け、協会内でさまざまな報酬と交換できます"
        },
        RESOURCE_DESC_4010001 = {
          ContentJP = "アトランティス大陸に生息するチョウの亜種。明るい緑色は春の訪れを象徴しているようだ。"
        },
        RESOURCE_DESC_4010002 = {
          ContentJP = "アトラシア大陸に生息するチョウの亜種。混じりけのない深い青色は澄み切っている。"
        },
        RESOURCE_DESC_4010003 = {
          ContentJP = "無味無臭の泉水。エリュシオンでは、人々はこれを神々からの贈り物と信じ、心身を清め、穢れを洗い流すものだと考えている。"
        },
        RESOURCE_DESC_4010004 = {
          ContentJP = "極寒の条件下でも生存できるキノコ。見た目は解ける前の雪のように見えるが、毒素を含んでおり、誤って食べると幻覚を引き起こし、ひどい場合は命の危険がある。\n\n絶対に、絶対に、絶対に食用不可！"
        },
        RESOURCE_DESC_4010005 = {
          ContentJP = "月ノ石を主な原材料とする液体。最も重要なエネルギー源として、ヒュペリアの国家運営を支えている。その用途は人々に知られている範囲を超えて多岐にわたる。"
        },
        RESOURCE_DESC_4010006 = {
          ContentJP = "アトランティス大陸でよく見られる花の一種。薬の材料や染料として用いられる。"
        },
        RESOURCE_DESC_4010007 = {
          ContentJP = "砂浜に貝殻が打ちあげられているのは日常的な光景だが、どこも欠けていない、色鮮やかな貝殻が拾えるのは運がいい。"
        },
        RESOURCE_DESC_4010008 = {
          ContentJP = "「寒さを好む淡水植物。「冬の蓮花」とも呼ばれる。種子は透明で、泡のようにはかなく壊れやすい。\n\n猛毒注意！"
        },
        RESOURCE_DESC_4010009 = {
          ContentJP = "大型施設に必須の緊急エネルギー供給装置。あらかじめ調整されたイコル液が内蔵されており、長期間にわたり起動状態を維持できる。機械に設けられたエネルギースロットに差し込むだけで使用可能。"
        },
        RESOURCE_DESC_4010010 = {
          ContentJP = "ありふれた小さな花で、正式な名前はなく、地域ごとにさまざまな呼び名がある。\nほとんど注目されることもなく、意図的に植えられることもないが、どれだけ摘まれても、しばらくすれば再びたくさん咲き誇る、驚くべき生命力を持っている。"
        },
        RESOURCE_DESC_4010011 = {
          ContentJP = "レンガや石の隙間に根付く植物で、湿った環境を好むが、強い光や放射線にも耐えられる。寒さ、乾燥、痩せた土地にも強く、土壌条件をほとんど選ばない。中には、壁に聖音スズランの種を撒き、翌年には天然の壁飾りとして楽しむ人もいる。"
        },
        RESOURCE_DESC_4010012 = {
          ContentJP = "木々の茂る場所でよく見られ、辺境地域では鳥の卵を朝食にする習慣もある。できるだけ家の近くの鳥の卵を盗らないほうがいい。巣の主に見つかれば、家のガラス窓は二度ときれいにならないかもしれない。"
        },
        RESOURCE_DESC_4010013 = {
          ContentJP = "食用可能なキノコの一種で、風味豊かであり、大陸全土に広く分布している。\nほぼすべての国の人々が、それぞれ独自の調理法を持っている。"
        },
        RESOURCE_DESC_4010014 = {
          ContentJP = "華胥でもっともありふれ、同時にもっとも重要な花。花開けば香りがあたりに満ち、香料の素材として華胥の人々によく使われている。一摘みで折れてしまうほどか弱い草花こそが、大風九章という巨大な法度を支えているのだ。"
        },
        RESOURCE_DESC_4010015 = {
          ContentJP = "燭陰の禍がもたらした産物。この結晶は一帯の草木の成長を抑え、その区域の生態を徐々に停滞させてしまう。その理不尽な性質から、「匪石」と呼ばれている。"
        },
        RESOURCE_DESC_4010016 = {
          ContentJP = "鴉の孤原のあちこちに転がる壊れた武器の数々。そのいくつかは水に流され、微茫市へと辿り着いた。懸衡派と機枢派が歩んだ暗い歴史を見届けてきた証人でもあるそれらが、もし口を持ち、見聞きしたことを正直に語れたなら――今日の華胥は、きっとまったく違う姿になっていただろう。"
        },
        RESOURCE_DESC_4010017 = {
          ContentJP = "華胥でよく見られる昆虫の一種。鳴き声が機織り機の音にそっくりだと言われ、その名が付いた。周囲の環境に合わせて体色を変える性質があり、夏の草むらや林の中でそれを探すのは、子どもたちの定番の遊びとなっている。"
        },
        RESOURCE_DESC_4010018 = {
          ContentJP = "別名・地竜。岩肌に腹ばいになって日向ぼっこをするのが大好きだが、驚くほど用心深く、石を伝って地面の震えを感じ取ると、たちまち岩の裂け目に潜り込んでしまう。中にはこれをペットとして飼う者もおり、澄んだ青色の尾の手触りが、意外に人気なのだとか。"
        },
        RESOURCE_DESC_4010019 = {
          ContentJP = "いつもじっと空を見上げ、まるで天と語り合っているかのような蛙の一種。経験豊かな農夫なら誰もが知っている――アメカエルがしきりに鳴き始めたら、にわか雨が近い証拠。干している穀物を、そろそろ倉にしまう頃合いだと。"
        },
        RESOURCE_DESC_4010020 = {
          ContentJP = "もとはどこにでもいる普通の碧の蝶であり、かつての塵砂の荒海もまた、生命に満ちた緑の地であった。しかし燭陰の禍が、この土地のすべてを少しずつ蝕め、やがて不吉な黒紫に変えてしまった。"
        },
        RESOURCE_DESC_4020001 = {
          ContentJP = "かなり大きな褐色のナッツ。食用可能――ただし、岩のように硬い殻をげっ歯類のようにこじ開けられるならの話だが。"
        },
        RESOURCE_DESC_4020002 = {
          ContentJP = "珍しい殻付きナッツ。食用可能。通常のナッツよりも油分が豊富で、暖炉で焼くと自然に殻が弾ける。子どもたちに人気のおやつ。"
        },
        RESOURCE_DESC_4020003 = {
          ContentJP = "銀色に輝く鉱石。純度の濃さによって、黒から銀色までさまざまなバリエーションのメタリックな光沢を持つ。染料や顔料の材料として用いられる。"
        },
        RESOURCE_DESC_4020004 = {
          ContentJP = "さらに珍しい銀輝石。雑物が混じることにより、光沢がさらに鮮やかになっている。染料や顔料の材料として用いられる。"
        },
        RESOURCE_DESC_4020005 = {
