        UIGuide_Title_WallJump = {
          ContentJP = "クライミング"
        },
        UIGuide_TongLv_1 = {
          ContentJP = "一部のキャラクターは、固有の同調武器を持っている。同調武器はキャラクターのレベルに応じて自動的に成長し、武器の変更や個別育成は行えないが、魔の楔を装着することはできる。"
        },
        UIGuide_TrainingGround_1 = {
          ContentJP = "「砂海の瞑想」では、過去に戦った敵と回想のなかで戦うことができます。敵の戦い方を学んで、自分の腕前を上げましょう。"
        },
        UIGuide_TrainingGround_2 = {
          ContentJP = "「砂海の瞑想」の<H>砂海の渦</>では、<H>弾薬補給箱</>、<H>気つけ薬</>、<H>興奮剤</>などの戦闘が便利になるアイテムがドロップします。"
        },
        UIGuide_TrainingGround_3_PC = {
          ContentJP = "<H>右上</>の<H>キャラクター</>画面でキャラクターを切り替えできます。"
        },
        UIGuide_TrainingGround_3_Phone = {
          ContentJP = "<H>右上</>の<H>キャラクター</>画面でキャラクターを切り替えできます。"
        },
        UIGuide_TrainingGround_4_PC = {
          ContentJP = "「砂海の瞑想」で&OpenMenu&を押すと、<H>「砂海の瞑想」を離れる</>を選択することができます。"
        },
        UIGuide_TrainingGround_4_Phone = {
          ContentJP = "<H>左上</>の<H>メニュー</>から<H>「砂海の瞑想」を離れる</>ことができます。"
        },
        UIGuide_TrialRank_1 = {
          ContentJP = "キャラクター・武器・ジェネモン・魔の楔を育成し、クエスト達成で経験値を獲得して、冒険レベルを上げましょう。"
        },
        UIGuide_TrialRank_2 = {
          ContentJP = "一定の冒険レベルに到達すると、豪華な報酬と強化効果を獲得できます。"
        },
        UIGuide_TriggerEffect_1 = {
          ContentJP = "元素属性は<H>キャラクター</>によって付与されます。<H>水・火・風・雷・光・闇</>の6種の元素属性が持つ<H>追加効果</>は、対象に対応する属性の<H>持続ダメージ</>のデバフを付与します。\n 水属性：水属性の持続ダメージを付与。\n 火属性：火属性の持続ダメージを付与。\n 雷属性：雷属性の持続ダメージを付与。\n 風属性：風属性の持続ダメージを付与。\n 光属性：光属性の持続ダメージを付与し、同時に全ての属性追加効果の残り時間を<H>リセット</>する。\n 闇属性：闇属性の持続ダメージを付与し、同時に体勢回復速度ダウンの効果を<H>スタック</>させる。"
        },
        UIGuide_TriggerEffect_2 = {
          ContentJP = "物理属性は<H>武器</>によって付与されます。<H>切断・貫通・衝撃</>の三つの物理属性が持つ<H>追加効果</>は、その物理属性のダメージや体勢削り効果をアップさせます。\n 切断属性：<H>シールド</>へのダメージがアップ。\n 貫通属性：<H>HP</>へのダメージがアップ。\n 衝撃属性：その攻撃による<H>体勢削り</>効果がアップ。"
        },
        UIGuide_TriggerEffect_3 = {
          ContentJP = "武器や一部スキルでダメージを与えると、対応する属性の<H>追加効果</>が発動することがあります。発動率は武器の<H>発動確率</>に依存します。"
        },
        UIGuide_TurnTable = {
          ContentJP = "一般的な扉のロック機構。規定時間内にすべての白いエリアを点灯させることで魔法ロックを解除できます。"
        },
        UIGuide_ValveMechanism = {
          ContentJP = "一般的な扉のロック機構。規定時間内にカーソルを終点までドラッグすることで魔法ロックを解除できます。"
        },
        UIGuide_WIKI_01 = {
          ContentJP = "ストーリー会話中に見慣れない用語が出てきたら、右下に<H>用語確認</>ボタンがないかチェックしてみましょう。タップすれば対応する用語の説明を確認できます。"
        },
        UIGuide_WIKI_02 = {
          ContentJP = "<H>百科事典</>では、これまでに見たすべての用語を確認できます。"
        },
        UIGuide_WallJump_PC = {
          ContentJP = "壁に密着した状態で&Jump&を<H>連続</>で押すと、壁を登ります。"
        },
        UIGuide_WallJump_Phone = {
          ContentJP = "壁に密着した状態でボタンを<H>連続</>で押すと、壁を登ります。"
        },
        UIGuide_WangXi_1 = {
          ContentJP = "裂け目は、落ちた生き物を絶えず蝕んでいく。裂け目の環境下では、あなたのHPは絶え間なく減少する。"
        },
        UIGuide_WangXi_2 = {
          ContentJP = "裂け目の内部には三途の川の水が満ちている。その水に触れると、HPの減少速度が大きく増える。"
        },
        UIGuide_WangXi_3 = {
          ContentJP = "灯籠で作られる安全地帯をうまく活用することが、裂け目から脱出する鍵となる。"
        },
        UIGuide_WuYou_1 = {
          ContentJP = "指定数の敵を倒すと超凶悪戦闘に突入できます"
        },
        UIGuide_WuYou_2 = {
          ContentJP = "戦闘中に敵を倒すことでムユウセイを強化できます"
        },
        UIGuide_WuYou_3 = {
          ContentJP = "指定時間内にクリアして報酬目標を達成しましょう"
        },
        UIGuide_XiQiu_1 = {
          ContentJP = "機巧制御盤の牽引機能を使えば、機巧球を対応する台座へと引き寄せ、トラップを解除できる。"
        },
        UIGuide_XianJing_1 = {
          ContentJP = "この種の容器は、外見上は通常の宝物入り容器と何ら変わらない。毒煙容器としばらく接触すると、容器内から一定範囲に毒煙が噴き出し、毒煙の範囲内にいると中毒して体力が徐々に減少する。時間の経過とともに、毒煙もやがて消散する。"
        },
        UIGuide_XiaoChuan_1 = {
          ContentJP = "三途の川の水面には、<H>小船</>が漂っている。点火状態のとき、小船を中心に移動する安全地帯が生まれ、裂け目の侵蝕から身を守ってくれる。その安全地帯内では移動でき、HPも持続的に回復する。"
        },
        UIGuide_XiaoYao_1 = {
          ContentJP = "ショウヨウセイは時折、周囲の物体に憑依して異常な姿を見せることがある。機巧制御盤のスキャン機能を使えば、そうした物体を見分けられる。"
        },
        UIGuide_XiaoYao_2 = {
          ContentJP = "機巧制御盤を使うことで、異常な物体に憑依しているショウヨウセイを吸い取ることができる。"
        },
        UIGuide_XiaoYao_3 = {
          ContentJP = "姿を晒したショウヨウセイは逃走し、再び周囲の別の物体へ憑依することがある。\n ショウヨウセイの残した痕跡を追い、その身柄を確保せよ。\n 一定時間内にショウヨウセイを捕まえられなかった場合、その痕跡を見失い、追跡は失敗となる。"
        },
        UIGuide_XiaoYao_4 = {
          ContentJP = "逃走中のショウヨウセイは背後にムユウ径を残すことがあり、ムユウ径を使えばプレイヤーは別の場所へ素早く移動できる。"
        },
        UIGuide_XingShi_1 = {
          ContentJP = "<H>醒石碑</>を叩くと千枢狩陣の機関が起動し、フィールドの構造が変化する。"
        },
        UIGuide_XuanYong_1 = {
          ContentJP = "太虚陵には、先人の霊が宿る石人形が数多く点在している。石人形は破壊できるが、打ち砕くと先人の怒りを招き、敵や罠が現れることがある。"
        },
        UIGuide_YanQueFeiXing_1 = {
          ContentJP = "このコンテンツを開始するには、あらかじめタクティカルバッグに道具[機巧制御盤・邪払]を装備しておく必要があります。"
        },
        UIGuide_YanQueFeiXing_2 = {
          ContentJP = "からくり偃雀の経路誘導システムに不具合が発生しています。[機巧制御盤・邪払]で目的地まで誘導し、調整を行ってください。"
        },
        UIGuide_YanQueFeiXing_3 = {
          ContentJP = "偃雀の飛行中、内部に保存されていた[パーツ：復元機枢]がランダムに落下します。[機巧制御盤・邪払]で攻撃すると充電でき、偃雀を修復できます。"
        },
        UIGuide_YanQueFeiXing_4 = {
          ContentJP = "偃雀の飛行中、内部に保存されていた[電池：加速機枢]がランダムに落下します。[機巧制御盤・邪払]で攻撃すると、偃雀を加速させられます。"
        },
        UIGuide_YanQueFeiXing_5 = {
          ContentJP = "偃雀の飛行中、内部に保存されていた[接着剤：故障機枢]がランダムに落下します。[機巧制御盤・邪払]で攻撃すると、偃雀の走行が妨害され、速度が低下します。"
        },
        UIGuide_YanQueFeiXing_6 = {
          ContentJP = "偃雀が目的地に到達すれば調整完了となり、その時点で報酬を獲得できます。"
        },
        UIGuide_YanQue_1 = {
          ContentJP = "偃雀は決まった巡回経路に沿って移動する。見つからないよう注意せよ。"
        },
        UIGuide_YanQue_2 = {
          ContentJP = "背後から近づくことで、一定時間だけ偃雀を無力化できる。\n 無力化状態から回復すると、偃雀は元の経路に沿って巡回を再開する。"
        },
        UIGuide_YanShi_1 = {
          ContentJP = "一部の洞窟の入口は岩石で塞がれている。"
        },
        UIGuide_YanShi_2 = {
          ContentJP = "近接武器や遠隔武器で岩石を破壊できるが、近接武器のほうが効率よく壊せる。"
        },
        UIGuide_YinZong_1 = {
          ContentJP = "ショウヨウセイは時おり華胥の各地に現れる。接触後、一定範囲内でその足取りを見つければ、報酬を獲得できる。"
        },
        UIGuide_YuBo_1 = {
          ContentJP = "皓京城の一部の香炉は燭陰の禍の影響を深く受け、大風九章とのつながりをなかなか取り戻せずにいる。懸衡派の香官たちと力を合わせて燭陰の影響を取り除き、香炉を正常な状態に戻そう。"
        },
        UIGuide_YuBo_2 = {
          ContentJP = "浄化された香炉のみが正常に作動し、その地域の香の濃度を回復できる。"
        },
        UIGuide_YuBo_3 = {
          ContentJP = "燭陰の禍が残した一部の気団は、空気中の香料に刺激されると小さな気団へと分裂する。"
        },
        UIGuide_YuBo_4 = {
          ContentJP = "[機巧制御盤]を使って小さな気団を一か所に集め、過負荷で膨張させる必要がある"
        },
        UIGuide_YuBo_5 = {
          ContentJP = "膨張した燭陰の気団を攻撃すれば、浄化できる。"
        },
        UIGuide_ZhanFeng_1 = {
          ContentJP = "<H>風鈴</>を鳴らすと、あなたの願いに応じて、隠された機巧や失われた記憶が呼び覚まされる。"
        },
        UIGuide_ZhenLv_1 = {
          ContentJP = "応天尉は絶えず鎮律の石人へとチャージを行っており、その間、鎮律の石人は無敵状態となる。\n チャージが完了すると封鎖障壁が完全に形成され、戦闘失敗となる。"
        },
        UIGuide_ZhenLv_2 = {
          ContentJP = "鎮律の石人へのチャージを行っている応天尉を倒して初めて、鎮律の石人の無敵状態を解除できる。\n この時に鎮律の石人を攻撃すればダメージを与えられ、二体の鎮律の石人をともに破壊すると封鎖が解除される。"
        },
        UIGuide_ZhengLi_1 = {
          ContentJP = "アイテムがすべて配置可能マス内にある時、そのアイテムをバッグに入れることができ、対応する基本スコアを獲得する。"
