        },
        UI_WEAPON_DESC_20302 = {
          ContentJP = "夜の帳、赤き舞踏靴、バラに滴る露水。髪先を掠める吐息、突如として響く銃声、霧散する硝煙――これが、究極にして最高の宴。"
        },
        UI_WEAPON_DESC_20303 = {
          ContentJP = "自然へ還る最も誠実な方法とは――灰となって、大地へと溶けることだ。"
        },
        UI_WEAPON_DESC_20304 = {
          ContentJP = "青銅は機巧の骨を鍛え、棘は虚無に帰し英魂を鋳造する。"
        },
        UI_WEAPON_DESC_20305 = {
          ContentJP = "業火は数千の銀白なる薬莢と共に大地へと降り注ぎ、神明の勅令をあまねく異端者の胸に刻み込む"
        },
        UI_WEAPON_DESC_20398 = {
          ContentJP = "最新技術で鍛えられた榴弾砲。勇猛な城砕きたちの得物。"
        },
        UI_WEAPON_DESC_20399 = {
          ContentJP = "ここ数年で発展した精錬技術と金メッキ技術を駆使して製造されたランチャー。鍛冶職人たちのお薦めの武器で、費用対効果も高く、アトラシアの旅人の間で人気が高い。"
        },
        UI_WEAPON_DESC_20401 = {
          ContentJP = "嘆きあってこそ、世界は静寂を取り戻す。"
        },
        UI_WEAPON_DESC_20402 = {
          ContentJP = "体躯に種を埋め込み、破滅の花を咲かせる。"
        },
        UI_WEAPON_DESC_20403 = {
          ContentJP = "エリュシオン礼賛会の聖アイリス騎士団が愛用する銃器――聖なるかな。我ら九神の福音、アトラシアの隅々にまで響かしめん。"
        },
        UI_WEAPON_DESC_20405 = {
          ContentJP = "……ん？アトラシアが滅びるって？どうでもいい、爆発しろ。"
        },
        UI_WEAPON_DESC_20406 = {
          ContentJP = "敵を退けるのは砲撃の響きのみならず、鋼鉄の鋸歯もまた然り。"
        },
        UI_WEAPON_DESC_20407 = {
          ContentJP = "群れから離れし孤影は機枢を廻らし、一羽で天を回らす。"
        },
        UI_WEAPON_DESC_20498 = {
          ContentJP = "最新技術で鍛えられた散弾銃。熟練の狩人たちに好まれている。"
        },
        UI_WEAPON_DESC_20499 = {
          ContentJP = "ありふれた散弾銃。最安価な金属で作られているので、壊れても惜しくない。"
        },
        UI_WEAPON_DESC_20501 = {
          ContentJP = "弾丸がもたらす魂を抉る痛みに、善と正義と勇気は耐えられるのか？"
        },
        UI_WEAPON_DESC_20502 = {
          ContentJP = "フォーセイクン同盟の「レイブン」たちが愛用する銃器。聞け！これこそが追放された者の怒り！帝国がために鳴らす弔いの鐘音なのだ！"
        },
        UI_WEAPON_DESC_20503 = {
          ContentJP = "エリュシオン礼賛会の聖アイリス騎士団が愛用する火炎放射器――聖なるかな。我が身に浄化の火を降臨させ給え。神の御名にて、あらゆる邪悪を焼き尽くさん。"
        },
        UI_WEAPON_DESC_20504 = {
          ContentJP = "エリュシオン礼賛会の聖アイリス騎士団が使用するアサルトライフル――聖なるかな！たとえ道が茨で満ちていようとも、天の光が輝くその一瞬のため、我らは喜んでその道を突き進もう。"
        },
        UI_WEAPON_DESC_20505 = {
          ContentJP = "三辺の構造は女神に讃えられ、美の芸術を致命の鋭刃へと変えることを願う。"
        },
        UI_WEAPON_DESC_20506 = {
          ContentJP = "相生の孔雀は雲屏を開き、錦花のしとねにたおやかに舞ふ。"
        },
        UI_WEAPON_DESC_20507 = {
          ContentJP = "若い船乗りは、いつも大波に備えて船の帆をたたむのに忙しく、波の下に秘められた愛の囁きを耳に傾けたことはなく、彼だけに捧げられた人魚の歌声に気がつくこともなかった。"
        },
        UI_WEAPON_DESC_20509 = {
          ContentJP = "私は雪白の羽根ペンで、小さな檻を編んだ──荒ぶる世界を閉じ込めるために。"
        },
        UI_WEAPON_DESC_20510 = {
          ContentJP = "夢に寒江の月を斬り、剣先に秋光ひとすじ。"
        },
        UI_WEAPON_DESC_20511 = {
          ContentJP = "血で、黄昏の誓約を刻む。"
        },
        UI_WEAPON_DESC_20512 = {
          ContentJP = "揺らめく琥珀色の光が、夢うつつにとどまる。炉火の微温は、いまだ絶えず。"
        },
        UI_WEAPON_DESC_20598 = {
          ContentJP = "最新技術で鍛えられたアサルトライフル。荒々しい先鋒たちに重宝される。"
        },
        UI_WEAPON_DESC_20599 = {
          ContentJP = "武器を手にした者のひとりは名医だった。父なる神はその慈悲を称えた。彼女は人々の心に張られた感情の弦と共鳴し、琴線の律動でざわめく心を鎮めた。\n だがこの世には、棘のように蔓延る苦しみがあまりにも多かった。ゆえに彼女は毒を精製し、その苦しみを生み出す肉体ごと取り除こうとした。\n やがて脆い琴弦はそれ以上に耐えきれず断ち切れ、彼女は自ら調合した毒を飲まされ、眠ることも醒めることもできない長い夜へと堕ちていった。"
        },
        UI_WEAPON_DESC_20601 = {
          ContentJP = "孤独な者よ、烈火に身を浸し、風に散る黄砂となることを厭わないならば、それこそが再生の瞬間なのだ。"
        },
        UI_WEAPON_DESC_20602 = {
          ContentJP = "弓の弦が震え、敵は射程内にいる。落ち着け、友よ──敵はもう逃げられない。"
        },
        UI_WEAPON_DESC_20603 = {
          ContentJP = "誰も知らないニヴルヘイムの果て――その原初の混沌に、小さな花は咲いたのか。"
        },
        UI_WEAPON_DESC_20604 = {
          ContentJP = "張り詰めた生死の弦は、魂を裂く哀歌を奏でる。"
        },
        UI_WEAPON_DESC_20698 = {
          ContentJP = "最新技術で鍛えられた弓。潜伏任務に長けた斥候の愛用品。"
        },
        UI_WEAPON_DESC_20699 = {
          ContentJP = "ありふれた弓。安価な金属製で、壊れても惜しくない。"
        },
        UI_WEAPON_DESC_310101 = {
          ContentJP = "「いったいアタシの何を気に入ったってんだ？お前なんざにくれてやれるものなんて微塵もねぇ。はなからアタシはなんにも持っちゃいねぇのにさ」\n「いえ、リーン。あなたは持っている。私が欲しいのは、あなたの『夢』よ」"
        },
        UI_WEAPON_DESC_530101 = {
          ContentJP = "飛べ、飛ぶのだ。たとえ偽りの翼であっても、小さな花の種のように優しい風に乗って飛べるはず。城壁を越え、凍土を越えて、長い夜さえも飛び越えて、あの灼熱の昼へと向かって、あの暖かい太陽へと向かって。"
        },
